(function(global) {
  'use strict';

  const ROUND_HALF_UP = 4;
  const context = { precision: 40, rounding: ROUND_HALF_UP };
  const pow10Cache = [1n];

  function pow10(n) {
    if (n < 0) throw new Error('Negative exponent');
    while (pow10Cache.length <= n) {
      pow10Cache.push(pow10Cache[pow10Cache.length - 1] * 10n);
    }
    return pow10Cache[n];
  }

  function normalize(sign, int, scale) {
    if (int === 0n || sign === 0) {
      return { sign: 0, int: 0n, scale: 0 };
    }
    sign = sign < 0 ? -1 : 1;
    while (scale > 0 && int % 10n === 0n) {
      int /= 10n;
      scale -= 1;
    }
    return { sign, int, scale };
  }

  function parseString(str) {
    const s = String(str).trim();
    if (!s) throw new Error('Invalid Decimal value');
    const match = s.match(/^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/);
    if (!match) throw new Error('Invalid Decimal value');
    const sign = match[1] === '-' ? -1 : 1;
    const intPart = match[2] || '';
    const fracPart = match[3] || '';
    const exp = match[4] ? Number(match[4]) : 0;
    let digits = (intPart + fracPart).replace(/^0+/, '');
    let scale = fracPart.length - exp;
    if (scale < 0) {
      digits = digits + '0'.repeat(-scale);
      scale = 0;
    }
    if (!digits) {
      return { sign: 0, int: 0n, scale: 0 };
    }
    const int = BigInt(digits);
    return normalize(sign, int, scale);
  }

  function parseValue(value) {
    if (value instanceof Decimal) {
      return { sign: value.sign, int: value.int, scale: value.scale };
    }
    if (typeof value === 'bigint') {
      const sign = value === 0n ? 0 : (value < 0n ? -1 : 1);
      const int = value < 0n ? -value : value;
      return normalize(sign, int, 0);
    }
    if (typeof value === 'number') {
      if (!Number.isFinite(value)) throw new Error('Invalid Decimal value');
      return parseString(value.toString());
    }
    if (typeof value === 'string') {
      return parseString(value);
    }
    throw new TypeError('Unsupported Decimal input');
  }

  function createDecimal(sign, int, scale, applyPrecision) {
    const norm = normalize(sign, int, scale);
    const dec = Object.create(Decimal.prototype);
    dec.sign = norm.sign;
    dec.int = norm.int;
    dec.scale = norm.scale;
    if (applyPrecision !== false) dec._applyPrecision();
    return dec;
  }

  class Decimal {
    constructor(value) {
      const parsed = parseValue(value);
      this.sign = parsed.sign;
      this.int = parsed.int;
      this.scale = parsed.scale;
      this._applyPrecision();
    }

    static set(opts = {}) {
      if (typeof opts.precision === 'number' && Number.isFinite(opts.precision)) {
        const p = Math.max(0, Math.floor(opts.precision));
        context.precision = p;
      }
      if (typeof opts.rounding === 'number') {
        context.rounding = opts.rounding;
      }
      return { ...context };
    }

    static get precision() {
      return context.precision;
    }

    static get rounding() {
      return context.rounding;
    }

    static isDecimal(v) {
      return v instanceof Decimal;
    }

    clone() {
      return createDecimal(this.sign, this.int, this.scale, false);
    }

    plus(other) {
      const rhs = other instanceof Decimal ? other : new Decimal(other);
      if (this.sign === 0) return rhs.clone();
      if (rhs.sign === 0) return this.clone();
      const scale = Math.max(this.scale, rhs.scale);
      const a = this.int * pow10(scale - this.scale);
      const b = rhs.int * pow10(scale - rhs.scale);
      let sum = (this.sign === -1 ? -a : a) + (rhs.sign === -1 ? -b : b);
      if (sum === 0n) return createDecimal(0, 0n, 0);
      const sign = sum < 0n ? -1 : 1;
      if (sum < 0n) sum = -sum;
      return createDecimal(sign, sum, scale);
    }

    minus(other) {
      const rhs = other instanceof Decimal ? other : new Decimal(other);
      return this.plus(createDecimal(rhs.sign === 0 ? 0 : -rhs.sign, rhs.int, rhs.scale, false));
    }

    times(other) {
      const rhs = other instanceof Decimal ? other : new Decimal(other);
      if (this.sign === 0 || rhs.sign === 0) return createDecimal(0, 0n, 0);
      const sign = this.sign * rhs.sign;
      const int = this.int * rhs.int;
      const scale = this.scale + rhs.scale;
      return createDecimal(sign, int, scale);
    }

    div(other) {
      const rhs = other instanceof Decimal ? other : new Decimal(other);
      if (rhs.sign === 0) throw new Error('Division by zero');
      if (this.sign === 0) return createDecimal(0, 0n, 0);
      const scale = context.precision;
      const numerator = this.int * pow10(rhs.scale + scale);
      const denominator = rhs.int * pow10(this.scale);
      let q = numerator / denominator;
      let remainder = numerator % denominator;
      if (remainder !== 0n && context.rounding === ROUND_HALF_UP) {
        const twice = remainder * 2n;
        if (twice > denominator || twice === denominator) {
          q += 1n;
        }
      }
      return createDecimal(this.sign * rhs.sign, q, scale);
    }

    mod(other) {
      const rhs = other instanceof Decimal ? other : new Decimal(other);
      if (rhs.sign === 0) throw new Error('Division by zero');
      if (this.sign === 0) return createDecimal(0, 0n, 0);
      const scale = Math.max(this.scale, rhs.scale);
      const a = (this.sign === -1 ? -1n : 1n) * this.int * pow10(scale - this.scale);
      const b = (rhs.sign === -1 ? -1n : 1n) * rhs.int * pow10(scale - rhs.scale);
      let rem = a % b;
      if (rem === 0n) return createDecimal(0, 0n, 0);
      const sign = rem < 0n ? -1 : 1;
      if (rem < 0n) rem = -rem;
      return createDecimal(sign, rem, scale);
    }

    toFixed(dp = 0) {
      const decimals = Math.max(0, Math.floor(Number(dp) || 0));
      if (this.sign === 0) {
        return decimals === 0 ? '0' : `0.${'0'.repeat(decimals)}`;
      }
      let int = this.int;
      let scale = this.scale;
      if (scale > decimals) {
        const diff = scale - decimals;
        const factor = pow10(diff);
        const q = int / factor;
        const remainder = int % factor;
        int = q;
        if (remainder !== 0n && context.rounding === ROUND_HALF_UP) {
          const twice = remainder * 2n;
          if (twice > factor || twice === factor) {
            int += 1n;
          }
        }
        scale = decimals;
      } else if (scale < decimals) {
        int = int * pow10(decimals - scale);
        scale = decimals;
      }
      let digits = int.toString();
      if (scale === 0) {
        return (this.sign < 0 ? '-' : '') + digits;
      }
      if (digits.length <= scale) {
        digits = '0'.repeat(scale - digits.length + 1) + digits;
      }
      const idx = digits.length - scale;
      const intPart = digits.slice(0, idx) || '0';
      let fracPart = digits.slice(idx);
      if (fracPart.length < decimals) {
        fracPart = fracPart.padStart(decimals, '0');
      }
      return (this.sign < 0 ? '-' : '') + intPart + '.' + fracPart;
    }

    toString() {
      if (this.sign === 0) return '0';
      let digits = this.int.toString();
      const sign = this.sign < 0 ? '-' : '';
      if (this.scale === 0) return sign + digits;
      if (digits.length <= this.scale) {
        digits = '0'.repeat(this.scale - digits.length + 1) + digits;
      }
      const idx = digits.length - this.scale;
      const intPart = digits.slice(0, idx) || '0';
      let fracPart = digits.slice(idx).replace(/0+$/, '');
      if (!fracPart) return sign + intPart;
      return sign + intPart + '.' + fracPart;
    }

    valueOf() {
      return Number(this.toString());
    }

    toJSON() {
      return this.toString();
    }

    _normalize() {
      if (this.int === 0n || this.sign === 0) {
        this.sign = 0;
        this.int = 0n;
        this.scale = 0;
        return;
      }
      while (this.scale > 0 && this.int % 10n === 0n) {
        this.int /= 10n;
        this.scale -= 1;
      }
    }

    _applyPrecision() {
      if (this.sign === 0) {
        this.int = 0n;
        this.scale = 0;
        return;
      }
      const limit = context.precision;
      if (typeof limit !== 'number' || limit < 0) return;
      if (this.scale > limit) {
        const diff = this.scale - limit;
        const factor = pow10(diff);
        const q = this.int / factor;
        const remainder = this.int % factor;
        this.int = q;
        if (remainder !== 0n && context.rounding === ROUND_HALF_UP) {
          const twice = remainder * 2n;
          if (twice > factor || twice === factor) {
            this.int += 1n;
          }
        }
        this.scale = limit;
      }
      this._normalize();
    }
  }

  Decimal.ROUND_HALF_UP = ROUND_HALF_UP;

  Decimal.prototype.neg = function() {
    if (this.sign === 0) return createDecimal(0, 0n, 0);
    return createDecimal(-this.sign, this.int, this.scale, false);
  };

  Decimal.prototype.abs = function() {
    return createDecimal(this.sign < 0 ? 1 : this.sign, this.int, this.scale, false);
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = Decimal;
  }
  if (global && typeof global.Decimal === 'undefined') {
    global.Decimal = Decimal;
  }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
